#include <bits/stdc++.h>
using namespace std;

class FastScanner {
    static const int BUFSIZE = 1024;
    int idx, size;
    char buf[BUFSIZE];
    FILE* in;
public:
    FastScanner(FILE* _in = stdin) : idx(0), size(0), in(_in) {}

    inline char read() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, in);
            idx = 0;
            if (size == 0) return 0;
        }
        return buf[idx++];
    }

    inline void skip() {
        char c;
        do { c = read(); } while (c && (c <= ' '));
        idx--;
    }

    template<typename T>
    bool nextInt(T& out) {
        skip();
        char c = read();
        if (!c) return false;
        bool neg = false;
        if (c == '-') { neg = true; c = read(); }
        T val = 0;
        while (c >= '0' && c <= '9') {
            val = val * 10 + (c - '0');
            c = read();
        }
        out = neg ? -val : val;
        return true;
    }

    bool nextString(string& out) {
        skip();
        char c = read();
        if (!c) return false;
        out.clear();
        while (c > ' ') {
            out.push_back(c);
            c = read();
        }
        return true;
    }

    bool nextChar(char& out) {
        skip();
        char c = read();
        if (!c) return false;
        out = c;
        return true;
    }
};

FastScanner fs;
ostream& out = cout;

void solve() {
    int n;
    fs.nextInt(n);
    string s;
    fs.nextString(s);
    int r = 0;
    for (int i = 1; i < n; ++i) {
        if (s[i] == s[i-1]) r++;
    }
    out << r << '\n';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    out.flush();
    return 0;
}

